input.old_string:
model_comparison = {}
for alt in MODEL_NAMES:
    col = "distance_corrected" if alt == model else f"distance_{alt}"
    if col in data:
        model_comparison[alt] = float(
            _percent(data["distance"].mean(), data[col].mean()))

def stat_checks():
    for study, effect, df1, df2, f, p, kind, cite in pv.FSTATS:
        computed = float(stats.f.sf(f, df1, df2))
        if kind == "lt":
            ok = computed < p
            verdict = "consistent" if ok else "INCONSISTENT"
            reported_str = f"p < {p}"
        else:
            ok = abs(computed - p) <= 0.0006 + 10 ** -3 * 0.5
            verdict = "consistent" if ok else "INCONSISTENT"
            reported_str = f"p = {p}"
        sig_reported = (p < 0.05) if kind == "eq" else True
        sig_computed = computed < 0.05
        CHECKS.append({
            "id": f"stat-{study}-{effect}".replace(" ", "-"),
            "claim": f"{effect}: F({df1},{df2}) = {f}, {reported_str}",
            "citation": cite, "reported": p, "recomputed": round(computed, 5),
            "delta": round(computed - p, 5), "tolerance": 0.001,
            "verdict": verdict,
            "note": ("changes the significance decision at alpha = .05"
                     if sig_reported != sig_computed else ""),
        })

